package me.deltabilyard;
import com.fasterxml.jackson.databind.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.beans.factory.annotation.Value;
import java.util.*;
import java.time.Duration;

@RestController @RequestMapping("/api") public class Api {
 final Auth auth;final Games games;final String liveUrl,liveKey,liveSecret,botName,admin;final Bot bot;
 Api(Auth a,Games g,Bot bot,@Value("${app.livekit-url}")String url,@Value("${app.livekit-key}")String key,@Value("${app.livekit-secret}")String secret,@Value("${app.bot-name}")String name,@Value("${app.admin-key}")String admin){auth=a;games=g;this.bot=bot;liveUrl=url;liveKey=key;liveSecret=secret;botName=name;this.admin=admin;}
 long id(String token){return auth.verify(token);}
 @PostMapping("/auth") Map<String,Object> login(@RequestBody JsonNode n)throws Exception {Auth.User u=auth.login(n.path("initData").asText());auth.online(u.id());return Map.of("user",u,"token",auth.token(u),"botName",botName);}
 @GetMapping("/me") Map<String,Object> me(@RequestHeader("Authorization")String t){long id=id(t);auth.online(id);return Map.of("user",auth.user(id),"rooms",games.rooms.values().stream().filter(r->!r.phase.equals("FINISHED")&&r.seats.stream().anyMatch(s->s.user.id()==id)).toList());}
 @PostMapping("/rooms") Games.Room create(@RequestHeader("Authorization")String t,@RequestBody JsonNode n){long id=id(t);auth.limit("create:"+id,10,60);return games.create(id,n);}
 @PostMapping("/rooms/{code}/join") Games.Room join(@RequestHeader("Authorization")String t,@PathVariable String code){return games.join(code,id(t));}
 @GetMapping("/rooms/{code}") Games.Room room(@RequestHeader("Authorization")String t,@PathVariable String code){return games.get(code,id(t));}
 @PostMapping("/rooms/{code}/command") Map<String,Boolean> command(@RequestHeader("Authorization")String t,@PathVariable String code,@RequestBody JsonNode n){long id=id(t);auth.limit("command:"+id,40,10);games.command(code,id,n);return Map.of("ok",true);}
 @PostMapping("/rooms/{code}/ticket") Map<String,String> ticket(@RequestHeader("Authorization")String t,@PathVariable String code){long id=id(t);games.get(code,id);String ticket=UUID.randomUUID().toString();auth.redis.opsForValue().set("ticket:"+ticket,id+":"+code,Duration.ofSeconds(30));return Map.of("ticket",ticket);}
 @PostMapping("/rooms/{code}/voice") Map<String,String> voice(@RequestHeader("Authorization")String t,@PathVariable String code){long id=id(t);Games.Room r=games.get(code,id);if(r.phase.equals("FINISHED"))throw new IllegalArgumentException("Матч завершён");if(liveUrl.isBlank()||liveKey.isBlank()||liveSecret.isBlank())throw new IllegalArgumentException("Голосовой сервер ещё не настроен");long now=System.currentTimeMillis()/1000;String token=auth.jwt(Map.of("iss",liveKey,"sub",String.valueOf(id),"name",auth.user(id).name(),"nbf",now-10,"exp",now+300,"video",Map.of("roomJoin",true,"room",r.id,"canPublish",true,"canSubscribe",true,"canPublishSources",List.of("microphone"))),liveSecret);return Map.of("url",liveUrl,"token",token);}
 @GetMapping("/players") List<Auth.User> search(@RequestHeader("Authorization")String t,@RequestParam String q){long id=id(t);auth.limit("search:"+id,20,60);String query=q.replace("@","").trim();if(query.length()<2)return List.of();return auth.db.query("SELECT * FROM players WHERE id<>? AND (lower(username) LIKE lower(?) OR lower(name) LIKE lower(?)) LIMIT 20",(r,i)->new Auth.User(r.getLong("id"),r.getString("name"),r.getString("username"),r.getString("avatar")),id,"%"+query.replace("%","").replace("_","")+"%","%"+query.replace("%","").replace("_","")+"%");}
 @GetMapping("/friends") List<Map<String,Object>> friends(@RequestHeader("Authorization")String t){long id=id(t);return auth.db.query("SELECT p.*,r.status,r.sender FROM relationships r JOIN players p ON p.id=CASE WHEN r.sender=? THEN r.recipient ELSE r.sender END WHERE (r.sender=? OR r.recipient=?)",(r,i)->{Map<String,Object> m=new HashMap<>();long other=r.getLong("id");m.put("user",new Auth.User(other,r.getString("name"),r.getString("username"),r.getString("avatar")));m.put("status",r.getString("status"));m.put("incoming",r.getLong("sender")!=id);m.put("online",Boolean.TRUE.equals(auth.redis.hasKey("online:"+other)));return m;},id,id,id);}
 @PostMapping("/friends/{other}/{action}") Map<String,Boolean> relationship(@RequestHeader("Authorization")String t,@PathVariable long other,@PathVariable String action){long id=id(t);if(other==id)throw new IllegalArgumentException("Это ваш профиль");auth.limit("friend:"+id,20,60);auth.user(other);
  if(action.equals("block")){auth.db.update("DELETE FROM relationships WHERE sender=? AND recipient=?",other,id);auth.db.update("INSERT INTO relationships VALUES (?,?,'blocked') ON CONFLICT(sender,recipient) DO UPDATE SET status='blocked'",id,other);}
  else if(action.equals("remove")){auth.db.update("DELETE FROM relationships WHERE (sender=? AND recipient=?) OR (sender=? AND recipient=? AND status<>'blocked')",id,other,other,id);}
  else {Integer blocked=auth.db.queryForObject("SELECT count(*) FROM relationships WHERE status='blocked' AND ((sender=? AND recipient=?) OR (sender=? AND recipient=?))",Integer.class,id,other,other,id);if(blocked!=null&&blocked>0)throw new IllegalArgumentException("Действие недоступно");
   if(action.equals("accept")){auth.db.update("UPDATE relationships SET status='accepted' WHERE sender=? AND recipient=? AND status='pending'",other,id);}
   else if(action.equals("request")){Integer exists=auth.db.queryForObject("SELECT count(*) FROM relationships WHERE (sender=? AND recipient=?) OR (sender=? AND recipient=?)",Integer.class,id,other,other,id);if(exists!=null&&exists==0)auth.db.update("INSERT INTO relationships VALUES (?,?,'pending') ON CONFLICT DO NOTHING",id,other);}
   else throw new IllegalArgumentException("Неизвестное действие");
  }return Map.of("ok",true);
 }
 @PostMapping("/rooms/{code}/invite/{other}") Map<String,Boolean> invite(@RequestHeader("Authorization")String t,@PathVariable String code,@PathVariable long other){long id=id(t);games.get(code,id);auth.limit("invite:"+id,10,60);Integer friends=auth.db.queryForObject("SELECT count(*) FROM relationships WHERE status='accepted' AND ((sender=? AND recipient=?) OR (sender=? AND recipient=?))",Integer.class,id,other,other,id);if(friends==null||friends==0)throw new IllegalArgumentException("Сначала добавьте игрока в друзья");bot.invite(other,auth.user(id).name(),code);return Map.of("ok",true);}
 @GetMapping("/history") List<Map<String,Object>> history(@RequestHeader("Authorization")String t){long id=id(t);return auth.db.queryForList("SELECT id,room_code,finished_at,state->'scores' AS scores,state->>'message' AS message FROM matches WHERE jsonb_path_exists(state, '$.seats[*].user.id ? (@ == $id)', jsonb_build_object('id',?::bigint)) ORDER BY finished_at DESC LIMIT 20",id);}
 @PostMapping("/admin/drain") Map<String,Object> drain(@RequestHeader("X-Admin-Key")String key,@RequestParam(defaultValue="true")boolean enabled){if(!java.security.MessageDigest.isEqual(key.getBytes(java.nio.charset.StandardCharsets.UTF_8),admin.getBytes(java.nio.charset.StandardCharsets.UTF_8)))throw new IllegalArgumentException("Access denied");games.draining=enabled;long active=games.rooms.values().stream().filter(r->Set.of("AIM","SHOT","ROUND_END").contains(r.phase)).count();return Map.of("active",active,"draining",enabled);}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()==null?"Неверный запрос":e.getMessage()));}
}
